static Optional<Integer> firstRepeat(List<Integer> values) {
    for (int i = 0; i < values.size(); i++) {
        for (int j = 0; j < i; j++) {
            if (values.get(i).equals(values.get(j))) return Optional.of(values.get(i));
        }
    }
    return Optional.empty();
}

